# make_diff.R: writes paper_equity/.contract/r0/RERUN_DIFF.md from runs/summary_numbers.rds.
# Run from index/ after make_results.R. Output path can be overridden with env RERUN_DIFF_PATH.
suppressMessages({library(dplyr);library(purrr);library(tidyr)})
x=readRDS("runs/summary_numbers.rds"); f=function(v,d=3) formatC(v,format="f",digits=d)
L=character(); add=function(...) L<<-c(L,paste0(...))
tbl=function(df){ add("| ",paste(names(df),collapse=" | ")," |"); add("|",paste(rep("---",ncol(df)),collapse="|"),"|"); for(i in seq_len(nrow(df))) add("| ",paste(df[i,],collapse=" | ")," |") }
add("# RERUN_DIFF: published vs fix-only vs rerun\n")
add("Pollutant 110 (PM2.5), 300 m zone, year 2022 unless stated. Generated by `equity/index/make_diff.R` from `index/runs/summary_numbers.rds` (written by `make_results.R`); every number is in `results.json`.\n")
add("Definitions: **published** = as printed (legacy normaliser (n-2)/3, absent groups scored 0, old emissions); **fix_only** = corrected index n/(2(n-1)) and absent groups not scored, old emissions; **rerun** (variant A) = corrected index, 2022 interpolated from new CAT 2020 and 2025 emissions.\n")
sm=function(v,i) x$SUMM[[v]][[i]]
add("## Headline\n")
add("- Overall mean: published ",f(sm("published","overall")$mean)," (SE ",f(sm("published","overall")$se),", range ",f(sm("published","overall")$min),"-",f(sm("published","overall")$max),") -> rerun ",f(sm("rerun","overall")$mean)," (SE ",f(sm("rerun","overall")$se),", range ",f(sm("rerun","overall")$min),"-",f(sm("rerun","overall")$max),").")
add("- Race mean ",f(sm("published","race")$mean)," -> ",f(sm("rerun","race")$mean),"; race range ",f(sm("published","race")$min),"-",f(sm("published","race")$max)," (gap ",f(sm("published","race")$max-sm("published","race")$min),") -> ",f(sm("rerun","race")$min),"-",f(sm("rerun","race")$max)," (gap ",f(sm("rerun","race")$max-sm("rerun","race")$min),").")
add("- Most of the change is the normaliser, not the emissions: fix_only and rerun differ by at most ",f(max(abs(x$T2$fix_only[,c("overall","income","race","edu","age")]-x$T2$rerun[,c("overall","income","race","edu","age")]))),". Education and age are unchanged by the fix (n = 4 groups; max diff published vs fix_only = ",f(x$chk_fix$max_abs_diff,9),").\n")
add("## (a) Table 2: published | fix_only | rerun\n")
for(idx in c("overall","income","race","edu","age")){
  add("**",idx,"**\n")
  d=x$T2$published %>% select(region,pub=all_of(idx)) %>% left_join(x$T2$fix_only %>% select(region,fix=all_of(idx)),by="region") %>% left_join(x$T2$rerun %>% select(region,rer=all_of(idx)),by="region") %>% mutate(across(-region,f))
  names(d)=c("Region","published","fix_only","rerun"); tbl(d); add("")
}
add("Summary (mean / SE / SD / min / max):\n")
d=map_dfr(c("overall","income","race","edu","age"),function(i) map_dfr(c("published","fix_only","rerun"),function(v){s=sm(v,i);tibble(index=i,run=v,mean=f(s$mean),se=f(s$se),sd=f(s$sd),min=f(s$min),max=f(s$max))}))
tbl(d); add("")
add("## (b) Race: equal-group (the paper's index) vs population-weighted (rerun)\n")
d=x$T2$rerun %>% transmute(Region=region,`n counties`=n_counties,`race equal-group`=f(race),`race pop-weighted`=f(race_pw),`overall equal-group`=f(overall),`overall pop-weighted`=f(total_pw)); tbl(d)
add("\nPopulation-weighted race scores range ",f(min(x$T2$rerun$race_pw)),"-",f(max(x$T2$rerun$race_pw)),"; the lowest region is ",x$T2$rerun$region[which.min(x$T2$rerun$race_pw)],", not Mohawk Valley (",f(x$T2$rerun$race_pw[x$T2$rerun$region=="Mohawk Valley"]),"). The two definitions rank regions differently on race; this is expected (equal-group weights a 0.1% group like any other) and is why both are reported.\n")
add("## (c) Emissions variants (corrected index)\n")
vs=c("rerun","exact_2020","exact_2025","exact_2022_38"); lab=c("A rerun (2022 interp.)","B exact 2020","C exact 2025","D exact 2022 (38 of 62 counties)")
for(idx in c("overall","race")){
 add("**",idx,"**\n")
 d=x$T2$rerun %>% select(region); for(k in seq_along(vs)) d[[lab[k]]]=f(x$T2[[vs[k]]][[idx]][match(d$region,x$T2[[vs[k]]]$region)])
 d$`n counties in D`=x$T2$exact_2022_38$n_counties[match(d$region,x$T2$exact_2022_38$region)]; names(d)[1]="Region"; tbl(d); add("")}
add("Rank of regions on race (1 = lowest) by variant:\n")
d=tibble(Region=x$T2$rerun$region); for(k in seq_along(vs)) d[[lab[k]]]=rank(x$T2[[vs[k]]]$race[match(d$Region,x$T2[[vs[k]]]$region)]); tbl(d); add("")
add("Variant D covers 38 of 62 counties (Kings, Nassau, Queens and 21 others absent), so some regions rest on 1 to 4 counties; it is a check, not a headline.\n")
add("## (d) In-text statistics: printed | published recomputed | rerun\n")
cr=function(v,k) x$CORR[[v]][[k]]$r; sl=function(v,y,w) x$SLOPES[[v]][[y]][[w]]; an=function(v,t,w) x$ANOVA[[v]][[t]]$group[[w]]
rows=list(
 c("overall mean (SE)","0.865 (0.020)",paste0(f(sm("published","overall")$mean)," (",f(sm("published","overall")$se),")"),paste0(f(sm("rerun","overall")$mean)," (",f(sm("rerun","overall")$se),")")),
 c("overall range","0.738-0.948",paste0(f(sm("published","overall")$min),"-",f(sm("published","overall")$max)),paste0(f(sm("rerun","overall")$min),"-",f(sm("rerun","overall")$max))),
 c("race range","0.142-0.851",paste0(f(sm("published","race")$min),"-",f(sm("published","race")$max)),paste0(f(sm("rerun","race")$min),"-",f(sm("rerun","race")$max))),
 c("race gap","0.709",f(sm("published","race")$max-sm("published","race")$min),f(sm("rerun","race")$max-sm("rerun","race")$min)),
 c("r(race, income)","+0.31",f(cr("published","r_race_income"),2),f(cr("rerun","r_race_income"),2)),
 c("r(total, race)","+0.97",f(cr("published","r_total_race"),2),f(cr("rerun","r_total_race"),2)),
 c("r(total, income)","+0.54",f(cr("published","r_total_income"),2),f(cr("rerun","r_total_income"),2)),
 c("r(income, edu) (not printed)","-",f(cr("published","r_income_edu"),2),f(cr("rerun","r_income_edu"),2)),
 c("r(emissions, race)","+0.76",f(cr("published","r_emissions_race"),2),f(cr("rerun","r_emissions_race"),2)),
 c("slope total: beta (p)","+0.11 (<0.001)",paste0(f(sl("published","total","beta"),3)," (",signif(sl("published","total","p"),2),")"),paste0(f(sl("rerun","total","beta"),3)," (",signif(sl("rerun","total","p"),2),")")),
 c("slope income: beta (p)","+0.06 (0.077)",paste0(f(sl("published","income","beta"),3)," (",signif(sl("published","income","p"),2),")"),paste0(f(sl("rerun","income","beta"),3)," (",signif(sl("rerun","income","p"),2),")")),
 c("slope race: beta (p)","+0.36 (0.002)",paste0(f(sl("published","race","beta"),3)," (",signif(sl("published","race","p"),2),")"),paste0(f(sl("rerun","race","beta"),3)," (",signif(sl("rerun","race","p"),2),")")))
for(t in list(c("race","1.27 (p>0.10)"),c("income","14.97 (p<0.001)"),c("age","11.41 (p<0.001)"),c("edu","5.074 (p<0.01)")))
 rows[[length(rows)+1]]=c(paste0("ANOVA F, ",t[1]," (group term)"),t[2],paste0(f(an("published",t[1],"F"),2)," (p=",signif(an("published",t[1],"p"),2),")"),paste0(f(an("rerun",t[1],"F"),2)," (p=",signif(an("rerun",t[1],"p"),2),")"))
rs=function(v,t,r) f(x$RSLOPES[[v]][[t]]$beta[x$RSLOPES[[v]][[t]]$region==r],3)
for(r in c("Long Island","New York City","Western New York","Southern Tier")) rows[[length(rows)+1]]=c(paste0("income slope, ",r),c("0","+0.001","-0.006","-0.006")[match(r,c("Long Island","New York City","Western New York","Southern Tier"))],rs("published","income",r),rs("rerun","income",r))
for(r in c("Southern Tier","Western New York","North Country","Mohawk Valley")) rows[[length(rows)+1]]=c(paste0("edu slope, ",r),c("-0.007","-0.013","+0.006","0")[match(r,c("Southern Tier","Western New York","North Country","Mohawk Valley"))],rs("published","edu",r),rs("rerun","edu",r))
rows[[length(rows)+1]]=c("sensitivity fit (slope on log km; intercept; sigma)","0.03; 0.91; 0.05",paste0(f(x$SENS_PUB$slope_log_km,3),"; ",f(x$SENS_PUB$intercept,3),"; ",f(x$SENS_PUB$sigma,3)),if(is.null(x$SENS_RERUN)) "TODO-recompute (run run_ny.R first)" else paste0(f(x$SENS_RERUN$slope_log_km,3),"; ",f(x$SENS_RERUN$intercept,3),"; ",f(x$SENS_RERUN$sigma,3)))
d=as.data.frame(do.call(rbind,rows)); names(d)=c("Statistic","Printed","Published recomputed","Rerun"); tbl(d)
add("\nWhich ANOVA term: the paper quotes row 1 of `broom::tidy(aov(epshare ~ group + region))`, the **group** term (get_bars2 caption: 'Differences by Group'). Race group F = 1.27 reproduces exactly (published). The manuscript prose attributes it to `region`, which is the second term; the region-term F is not the quoted number (published race region F = ",f(x$ANOVA$published$race$region$F,2),", p = ",signif(x$ANOVA$published$race$region$p,2),"; rerun F = ",f(x$ANOVA$rerun$race$region$F,2),", p = ",signif(x$ANOVA$rerun$race$region$p,2),"). Flag for T-007.\n")
add("Pearson r printed as +0.31 is the truncation of ",f(cr("published","r_race_income"),3)," (rounds to 0.32); the printed +0.54 and +0.76 round correctly.\n")
add("## (e) Do the findings still hold? (rerun, variant A)\n")
rr=x$T2$rerun; lowrace=rr$region[order(rr$race)][1:3]; lowrace_pub=x$T2$published$region[order(x$T2$published$race)][1:3]
means=sapply(c("income","race","edu","age"),function(i) sm("rerun",i)$mean)
add("| Finding | Holds? | Numbers |\n|---|---|---|")
add("| Race is the least even dimension | ",ifelse(names(which.min(means))=="race","YES","NO")," | means: ",paste(names(means),f(means),collapse=", ")," |")
add("| Mohawk Valley lowest overall | ",ifelse(rr$region[which.min(rr$overall)]=="Mohawk Valley","YES","NO")," | ",f(min(rr$overall))," (next lowest ",f(sort(rr$overall)[2])," ",rr$region[order(rr$overall)][2],") |")
add("| Same three upstate regions lowest on race (Mohawk Valley, North Country, Southern Tier) | ",ifelse(setequal(lowrace,lowrace_pub),"YES","NO (partly)")," | published lowest three: ",paste(lowrace_pub,collapse=", ")," ; rerun lowest three: ",paste(lowrace,collapse=", ")," ; North Country race ",f(rr$race[rr$region=="North Country"])," (rank ",rank(rr$race)[rr$region=="North Country"],") |")
add("| Higher-emission regions more even on race (r_emissions_race > 0) | ",ifelse(cr("rerun","r_emissions_race")>0,"YES","NO")," | r = ",f(cr("rerun","r_emissions_race"),2)," (published ",f(cr("published","r_emissions_race"),2),"); regression on log emissions, race beta ",f(sl("rerun","race","beta"),3)," p = ",signif(sl("rerun","race","p"),2)," (published ",f(sl("published","race","beta"),3),", p = ",signif(sl("published","race","p"),2),"); overall p = ",signif(sl("rerun","total","p"),2),"; income p = ",signif(sl("rerun","income","p"),2)," (no longer significant at 0.05; published 0.077) |")
add("| Income ANOVA significant | ",ifelse(an("rerun","income","p")<0.05,"YES","NO")," | F = ",f(an("rerun","income","F"),2),", p = ",signif(an("rerun","income","p"),2)," |")
add("| Race ANOVA not significant | ",ifelse(an("rerun","race","p")>0.05,"YES","NO")," | F = ",f(an("rerun","race","F"),2),", p = ",signif(an("rerun","race","p"),2)," |")
add("\nThe qualitative story survives; the magnitudes do not. Scores compress into 0.82-0.99, the race range collapses from 0.709 to ",f(sm("rerun","race")$max-sm("rerun","race")$min),", and the 'Mohawk Valley 0.14' sentence and the 0.709 gap must be rewritten (T-007). The three-lowest set changes at the margin (Finger Lakes ",f(rr$race[rr$region=="Finger Lakes"])," vs North Country ",f(rr$race[rr$region=="North Country"]),"). Under variants B, C, D the same ordering holds for Mohawk Valley and Southern Tier; check section (c).\n")
add("## (f) Not reproduced, and why\n")
add("- Printed Table 2 reproduces from stored published values to 3 d.p. (max |stored - printed| = ",signif(x$chk_t2$max_abs_diff_vs_printed_rounded,3),", i.e. rounding). The legacy formula applied to the published region_group_values reproduces the stored indicator2 exactly (max abs diff 0 for income, race, edu, age).")
add("- Printed +0.31 for r(race, income) is a truncation of 0.318 (see (d)).")
bad=x$DESC %>% filter(!match_printed)
add("- Descriptives (tab_descriptives2.tex), recomputed from the cached ACS 2022 file: ",nrow(x$DESC)-nrow(bad)," of ",nrow(x$DESC)," rows match. Mismatches: ",paste0(bad$variable," (",f(bad$mean_pct,2),"/",f(bad$sd_pct,2)," vs printed ",bad$printed_mean,"/",bad$printed_sd,")",collapse="; "),". Three are sub-0.1 rounding differences in the SD or mean. `edu_some_college_or_more` and `edu_postgrad` genuinely differ: the cached columns give 28.6% and 30.4% where the table prints 45.5% and 13.6%; the two sum to 59.1% in both, so the column-to-ID mapping in the cached census file (or the table labels) disagrees with B15003 IDs 019-021 / 022-025. Needs a look at make_data.R before the table is reused. ACS was not refetched.")
if(is.null(x$SENS_RERUN)) add("- Sensitivity rerun: not regenerated yet (`TODO-recompute`); run run_ny.R first.") else add("- Sensitivity fit (overall ~ log km, 10 regions x 5 distances): published slope ",f(x$SENS_PUB$slope_log_km,3),", intercept ",f(x$SENS_PUB$intercept,3),", sigma ",f(x$SENS_PUB$sigma,3),"; rerun slope ",f(x$SENS_RERUN$slope_log_km,3),", intercept ",f(x$SENS_RERUN$intercept,3),", sigma ",f(x$SENS_RERUN$sigma,3),".")
add("- Published table2 population-weighted columns are `TODO-recompute`: they did not exist in the published run (not computed on the old run).")
add("- Variant D: counties absent from the 2022 file drop out of each region; n per region is 1-7.\n")
add("---\n\n## For agents\n")
add("- Source: `equity/index/make_results.R` (headless, run from `index/`); runs in `index/runs/{variant_A,fix_only,variant_B,variant_C,variant_D}/stat_<type>_<year>_300_110.rds`; tidy numbers in `index/runs/summary_numbers.rds`; JSON in `paper_equity/.contract/r0/results.json` (keys table2, summary, correlations, emissions_slopes, anova, region_slopes, sensitivity, descriptives).")
add("- Variant keys: published, fix_only, rerun (=A), exact_2020 (=B), exact_2025 (=C), exact_2022_38 (=D).")
add("- r_emissions_race uses regional summed emissions interpolated to the variant year (as get_all's joined$emissions). The get_corr form (lm over CSV years, predict 2022): published ",f(x$CORR_getcorr$published,3),", fix_only ",f(x$CORR_getcorr$fix_only,3),", rerun ",f(x$CORR_getcorr$rerun,3),".")
add("- Emissions slopes: lm(index ~ log(regional emissions tons)) across 10 regions, as get_emissions_slopes (xtype 'Emissions').")
add("- ANOVA/region slopes: exactly the models in get_bars2. Quoted F is the `group` term.")
writeLines(L, Sys.getenv("RERUN_DIFF_PATH", "../../paper_equity/.contract/r0/RERUN_DIFF.md"))
